// ==========================================================
// BEFORE INHERITANCE: Code Duplication Everywhere
// ==========================================================
class BadDog {
    String name;
    void eat() {
        System.out.println(name + " is eating");
    }
    void bark() {
        System.out.println(name + " is barking: Woof!");
    }
}

class BadCat {
    String name; // Duplicated field!
    void eat() { // Duplicated method!
        System.out.println(name + " is eating");
    }
    void meow() {
        System.out.println(name + " is meowing: Meow!");
    }
}

// ==========================================================
// AFTER INHERITANCE: Clean, Reusable, and DRY
// ==========================================================
// 1. Parent Class: Contains shared fields and methods
class Animal {
    String name;

    void eat() {
        System.out.println(name + " is eating");
    }

    void sleep() {
        System.out.println(name + " is sleeping peacefully");
    }
}

// 2. Child Class: Reuses Animal and adds bark()
class Dog extends Animal {
    void bark() {
        System.out.println(name + " is barking: Woof!");
    }
}

// 3. Child Class: Reuses Animal and adds meow()
class Cat extends Animal {
    void meow() {
        System.out.println(name + " is meowing: Meow!");
    }
}

public class ZooDemo {
    public static void main(String[] args) {
        // Create a Dog object
        Dog myDog = new Dog();
        myDog.name = "Bruno";

        // Calling inherited methods from Animal
        myDog.eat();
        myDog.sleep();

        // Calling unique method from Dog
        myDog.bark();

        System.out.println("-----------------");

        // Create a Cat object
        Cat myCat = new Cat();
        myCat.name = "Luna";

        // Calling inherited methods from Animal
        myCat.eat();
        myCat.sleep();

        // Calling unique method from Cat
        myCat.meow();
    }
}

