class Animal {
    String name;
    int age;

    void eat() {
        System.out.println(name + " is eating food.");
    }
}

// Adding a Bird takes only 5 lines of code!
class Bird extends Animal {
    void fly() {
        System.out.println(name + " is flying high in the sky!");
    }
}

public class BirdDemo {
    public static void main(String[] args) {
        Bird parrot = new Bird();
        parrot.name = "Rio";
        parrot.age = 2;

        // Inherited method from Animal
        parrot.eat();

        // Bird-specific method
        parrot.fly();

        System.out.println(parrot.name + " is " + parrot.age + " years old.");
    }
}

